export const DEFAULT_VIBE_URL = 'https://vibecafe.ai';
export const DEFAULT_QUOTE_URL = 'https://dot.mindreset.tech';
export const DEFAULT_INTERVAL_MINUTES = 30;
export const MAX_INTERVAL_MINUTES = 44_640;

function readJson(path) {
  if (!existsSync(path)) return null;
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    throw new Error(`配置文件不是有效 JSON：${path}`);
  }
}

export function vibeConfigPath(env = process.env, options = {}) {
  const platform = options.platform ?? process.platform;
  const joinPath = pathJoin(platform);
  let home = options.home;
  if (!home && platform === 'win32') home = env.USERPROFILE;
  if (!home) home = homedir();
  return joinPath(home, '.vibe-usage', 'config.json');
}

function pathJoin(platform) {
  return platform === 'win32' ? win32.join : join;
}

function windowsRoot(env, variable, fallbackParts) {
  if (env[variable]) return env[variable];
  if (env.USERPROFILE) return win32.join(env.USERPROFILE, ...fallbackParts);
  throw new Error(`Windows 目录无法确定：缺少 ${variable} 和 USERPROFILE`);
}

export function quoteConfigPath(env = process.env, options = {}) {
  const platform = options.platform ?? process.platform;
  const joinPath = pathJoin(platform);
  let root = env.XDG_CONFIG_HOME;
  if (!root && platform === 'win32') {
    root = windowsRoot(env, 'APPDATA', ['AppData', 'Roaming']);
  }
  if (!root) root = joinPath(options.home ?? homedir(), '.config');
  return joinPath(root, 'vibe-usage-quote0', 'config.json');
}

export function dataDirectory(env = process.env, options = {}) {
  const platform = options.platform ?? process.platform;
  const joinPath = pathJoin(platform);
  let root = env.XDG_DATA_HOME;
  if (!root && platform === 'win32') {
    root = windowsRoot(env, 'LOCALAPPDATA', ['AppData', 'Local']);
  }
  if (!root) root = joinPath(options.home ?? homedir(), '.local', 'share');
  return joinPath(root, 'vibe-usage-quote0');
}

export function fileMode(path) {
  if (!existsSync(path)) return null;
  return statSync(path).mode & 0o777;
}

export function assertQuoteConfigMode(path, mode, platform = process.platform) {
  if (platform === 'win32' || mode === null || mode === 0o600) return;
  throw new Error(`Quote 配置权限必须为 0600：${path}`);
}

export function isVibeConfigModeInsecure(mode, platform = process.platform) {
  return platform !== 'win32' && mode !== null && (mode & 0o077) !== 0;
}

export function hardenVibeConfigMode(path, mode, platform = process.platform, options = {}) {
  if (!isVibeConfigModeInsecure(mode, platform)) return { mode, hardened: false };
  const changeMode = options.chmodSyncImpl ?? chmodSync;
  try {
    changeMode(path, 0o600);
  } catch (error) {
    throw new Error(`无法将 Vibe 配置权限收紧为 0600：${path}：${error?.message || String(error)}`);
  }
  const hardenedMode = (options.fileModeImpl ?? fileMode)(path);
  if (isVibeConfigModeInsecure(hardenedMode, platform)) {
    throw new Error(`Vibe 配置权限收紧后仍宽于 0600：${path}`);
  }
  return { mode: hardenedMode, hardened: true };
}

export function normalizeIntervalMinutes(value = DEFAULT_INTERVAL_MINUTES) {
  const normalized = typeof value === 'string' && /^\d+$/.test(value)
    ? Number(value)
    : value;
  if (
    !Number.isSafeInteger(normalized)
    || normalized < 1
    || normalized > MAX_INTERVAL_MINUTES
  ) {
    throw new Error(`刷新间隔必须是 1-${MAX_INTERVAL_MINUTES} 的整数分钟`);
  }
  return normalized;
}

export function loadQuoteSettings(env = process.env, options = {}) {
  const path = quoteConfigPath(env, options);
  const mode = fileMode(path);
  assertQuoteConfigMode(path, mode, options.platform ?? process.platform);
  const value = readJson(path) ?? {};
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`配置文件必须是 JSON 对象：${path}`);
  }
  return { path, value };
}

export function loadVibeConfig(env = process.env, options = {}) {
  const path = vibeConfigPath(env, options);
  const mode = fileMode(path);
  const permission = hardenVibeConfigMode(
    path,
    mode,
    options.platform ?? process.platform,
    options,
  );
  const file = readJson(path) ?? {};
  const apiKey = env.VIBE_USAGE_API_KEY || file.apiKey;
  const apiUrl = env.VIBE_USAGE_API_URL || file.apiUrl || DEFAULT_VIBE_URL;
  if (!apiKey) throw new Error('缺少 Vibe API key');
  return {
    apiKey,
    apiUrl,
    path,
    insecureMode: false,
    permissionHardened: permission.hardened,
  };
}

export function loadQuoteConfig(env = process.env, options = {}) {
  const { path, value: file } = loadQuoteSettings(env, options);
  const apiKey = env.QUOTE0_API_KEY || file.apiKey;
  const deviceId = env.QUOTE0_DEVICE_ID || file.deviceId;
  const taskKey = env.QUOTE0_TASK_KEY || file.taskKey;
  const apiUrl = env.QUOTE0_API_URL || file.apiUrl || DEFAULT_QUOTE_URL;
  const intervalMinutes = normalizeIntervalMinutes(file.intervalMinutes);
  if (!apiKey) throw new Error('缺少 QUOTE0_API_KEY 或 Quote 配置 apiKey');
  if (!deviceId) throw new Error('缺少 QUOTE0_DEVICE_ID 或 Quote 配置 deviceId');
  return { apiKey, deviceId, taskKey, apiUrl, intervalMinutes, path };
}
function finiteNonNegative(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : 0;
}

function addFiniteNonNegative(total, value) {
  const increment = finiteNonNegative(value);
  return total >= Number.MAX_VALUE - increment ? Number.MAX_VALUE : total + increment;
}

function bucketTotalTokens(bucket) {
  return addFiniteNonNegative(finiteNonNegative(bucket?.totalTokens), bucket?.cachedInputTokens);
}

function compactDecimal(value, decimals = 1) {
  return Number(value.toFixed(decimals)).toString();
}

const TOKEN_UNITS = [
  { divisor: 1, suffix: '' },
  { divisor: 10_000, suffix: '万' },
  { divisor: 100_000_000, suffix: '亿' },
  { divisor: 1_000_000_000_000, suffix: '万亿' },
];

function formatTokenUnit(number, initialUnitIndex) {
  let unitIndex = initialUnitIndex;
  while (unitIndex < TOKEN_UNITS.length) {
    const unit = TOKEN_UNITS[unitIndex];
    const scaled = number / unit.divisor;
    const integerDigits = Math.max(1, Math.floor(Math.log10(scaled)) + 1);
    const decimals = Math.max(0, 4 - integerDigits);
    const decimalFactor = 10 ** decimals;
    const rounded = Math.round(number / (unit.divisor / decimalFactor)) / decimalFactor;

    if (rounded < 10_000) {
      const value = unitIndex === 0 ? rounded.toLocaleString('zh-CN') : rounded.toString();
      return `${value}${unit.suffix}`;
    }
    unitIndex += 1;
  }
  return '9999万亿+';
}

export function truncateText(value, maxLength = 24) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!text) return '未知';
  return text.length <= maxLength ? text : `${text.slice(0, Math.max(1, maxLength - 1))}…`;
}

function aggregateRanking(buckets, key) {
  const totals = new Map();
  for (const bucket of buckets) {
    if (!bucket || typeof bucket !== 'object') continue;
    const name = truncateText(bucket[key], 24);
    totals.set(name, addFiniteNonNegative(totals.get(name) ?? 0, bucketTotalTokens(bucket)));
  }
  return [...totals.entries()]
    .map(([name, tokens]) => ({ name, tokens }))
    .sort((a, b) => b.tokens - a.tokens || a.name.localeCompare(b.name, 'zh-CN'))
    .slice(0, 3);
}

export function aggregateWindow(response) {
  const buckets = Array.isArray(response?.buckets) ? response.buckets : [];
  const sessions = Array.isArray(response?.sessions) ? response.sessions : [];
  let totalTokens = 0;
  let estimatedCost = 0;
  for (const bucket of buckets) {
    if (!bucket || typeof bucket !== 'object') continue;
    totalTokens = addFiniteNonNegative(totalTokens, bucketTotalTokens(bucket));
    estimatedCost += finiteNonNegative(bucket.estimatedCost);
  }
  let activeSeconds = 0;
  let sessionCount = 0;
  for (const session of sessions) {
    if (!session || typeof session !== 'object') continue;
    sessionCount += 1;
    activeSeconds += finiteNonNegative(session.activeSeconds);
  }
  return {
    totalTokens,
    estimatedCost: Math.round(estimatedCost * 1_000_000_000_000) / 1_000_000_000_000,
    sessionCount,
    activeSeconds,
    topTools: aggregateRanking(buckets, 'source'),
    topModels: aggregateRanking(buckets, 'model'),
    hasAnyData: totalTokens > 0 || estimatedCost > 0 || sessionCount > 0 || activeSeconds > 0,
  };
}

export function aggregateUsage(todayResponse, weekResponse) {
  return {
    today: aggregateWindow(todayResponse),
    week: aggregateWindow(weekResponse),
  };
}

export function formatTokens(value) {
  const number = finiteNonNegative(value);
  const unitIndex = TOKEN_UNITS.findLastIndex(({ divisor }) => number >= divisor);
  return formatTokenUnit(number, Math.max(0, unitIndex));
}

export function formatCost(value) {
  const number = finiteNonNegative(value);
  if (number >= 1_000_000_000_000) return '$9999亿+';
  if (number >= 100_000_000) {
    const scaled = number / 100_000_000;
    return `$${scaled >= 100 ? Math.round(scaled) : compactDecimal(scaled)}亿`;
  }
  if (number >= 10_000) {
    const scaled = number / 10_000;
    return `$${scaled >= 100 ? Math.round(scaled) : compactDecimal(scaled)}万`;
  }
  return `$${number.toFixed(2)}`;
}

export function formatCount(value) {
  const number = finiteNonNegative(value);
  if (number >= 100_000_000) return '9999万+';
  if (number >= 10_000) {
    const scaled = number / 10_000;
    return `${scaled >= 100 ? Math.round(scaled) : compactDecimal(scaled)}万`;
  }
  return Math.round(number).toLocaleString('zh-CN');
}

export function formatActiveTime(seconds) {
  const safe = finiteNonNegative(seconds);
  if (safe < 60) return `${Math.round(safe)}秒`;
  if (safe < 3600) return `${Math.round(safe / 60)}分钟`;
  if (safe < 3_600_000) return `${compactDecimal(safe / 3600)}小时`;
  if (safe < 31_557_600) return `${compactDecimal(safe / 86_400)}天`;
  if (safe < 3_155_760_000) return `${compactDecimal(safe / 31_557_600)}年`;
  return '100年+';
}
