function visitElements(value, types) {
  if (Array.isArray(value)) {
    for (const child of value) visitElements(child, types);
    return;
  }
  if (!value || typeof value !== 'object') return;
  if ('type' in value) {
    if (!ALLOWED_ELEMENT_TYPES.has(value.type)) throw new Error(`不支持的画板元素：${value.type}`);
    types.add(value.type);
  }
  for (const child of Object.values(value)) visitElements(child, types);
}

export function validateCanvasPayload(payload, forbiddenValues = []) {
  if (payload.refreshNow !== true) throw new Error('refreshNow 必须为 true');
  if (payload.taskAlias !== 'Vibe Usage') throw new Error('taskAlias 必须为 Vibe Usage');
  if (payload.border !== 0) throw new Error('border 必须为 0');
  if (!payload.data || typeof payload.data !== 'object') throw new Error('缺少 data');
  for (const key of Object.keys(payload.data)) {
    if (FORBIDDEN_DATA_KEYS.has(key)) throw new Error(`data 包含禁用字段：${key}`);
  }
  if (!Array.isArray(payload.windowData?.default)) throw new Error('windowData.default 必须为数组');
  const types = new Set();
  visitElements(payload.windowData.default, types);
  const serialized = JSON.stringify(payload);
  if (/project/i.test(serialized)) throw new Error('payload 不得包含 project');
  for (const secret of forbiddenValues.filter(Boolean)) {
    if (serialized.includes(String(secret))) throw new Error('payload 包含密钥');
  }
  return { elementTypes: [...types].sort(), bytes: Buffer.byteLength(serialized) };
}
import { InvalidResponseError, requestJson } from './http.js';

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function validateUsageResponse(value) {
  if (!isRecord(value)) throw new InvalidResponseError('Vibe 响应必须是对象');
  if (!Array.isArray(value.buckets)) throw new InvalidResponseError('Vibe 响应缺少 buckets 数组');
  if (!Array.isArray(value.sessions)) throw new InvalidResponseError('Vibe 响应缺少 sessions 数组');
  if (typeof value.hasAnyData !== 'boolean') throw new InvalidResponseError('Vibe 响应缺少 hasAnyData 布尔值');

  for (const [index, bucket] of value.buckets.entries()) {
    if (!isRecord(bucket)) throw new InvalidResponseError(`bucket[${index}] 必须是对象`);
    for (const field of ['source', 'model', 'totalTokens', 'cachedInputTokens', 'estimatedCost']) {
      if (!(field in bucket)) throw new InvalidResponseError(`bucket[${index}] 缺少 ${field}`);
    }
  }
  for (const [index, session] of value.sessions.entries()) {
    if (!isRecord(session)) throw new InvalidResponseError(`session[${index}] 必须是对象`);
    if (!('activeSeconds' in session)) throw new InvalidResponseError(`session[${index}] 缺少 activeSeconds`);
  }
  return value;
}

export async function fetchUsage({ apiUrl, apiKey, days, fetchImpl, logger, retryOptions = {} }) {
  const url = new URL('/api/usage', apiUrl);
  url.searchParams.set('days', String(days));
  const result = await requestJson(url, {
    apiKey,
    fetchImpl,
    validate: validateUsageResponse,
    logger,
    stage: `Vibe ${days}日用量`,
    identifier: `days-${days}`,
    ...retryOptions,
  });
  return result.data;
}
