        const answer = (await question(input, output, `${message}${suffix}`, false)).trim().toLowerCase();
        if (!answer) return defaultValue;
        if (answer === 'y' || answer === 'yes') return true;
        if (answer === 'n' || answer === 'no') return false;
        output.write('请输入 y 或 n。\n');
      }
